def _load_harvester():
    """The Factory's own harvest regexes, imported from the installed package
    when present, else the vendored copy of the same rules."""
    try:
        from app.factory.build.roles_handlers import _harvest_block_source  # type: ignore

        return _harvest_block_source
    except Exception:
        pass

    # Vendored fallback: the same harvest, re-implemented locally so the
    # generator runs in the delivered platform (no factory package there).
    KEY_RE = re.compile(
        r"""(?:payload|params|data|step|inputs?|body|record|config)\s*\.\s*get\(\s*["']([A-Za-z_][A-Za-z0-9_]*)["']"""
    )
    REQ_RE = re.compile(
        r"""["']([A-Za-z_][A-Za-z0-9_]*(?:\s+and\s+[A-Za-z_][A-Za-z0-9_]*)*)\s+required["']"""
    )
    ERR_RE = re.compile(r"""raise\s+\w*Error\(\s*["']([^"']{4,120})["']""")

    def _harvest_block_source(source: str) -> dict:
        keys = set(KEY_RE.findall(source))
        required: list = []
        for clause in REQ_RE.findall(source):
            for word in clause.split(" and "):
                word = word.strip()
                if word and word not in required:
                    required.append(word)
        errors = sorted(set(ERR_RE.findall(source)))
        return {"keys_read": sorted(keys), "required": required, "errors": errors}

    return _harvest_block_source


