def _handler_for(capability_id: str) -> Callable[[Dict[str, Any]], Dict[str, Any]]:
    """Load the capability's action module and return its handle().

    Import is per call so a broken handler is answered as a refused
    capability, never as a module import that takes the whole app down.
    """
    module = importlib.import_module("app.actions." + capability_id)
    return module.handle


def _refuse_caller_tenancy(payload: Dict[str, Any]) -> None:
    """Tenancy is resolved from the authenticated principal, never the body."""
    try:
        refuse_caller_tenancy(payload)
    except UnsafeInput as exc:
        raise HTTPException(status_code=422, detail=str(exc))


def _dispatch_capability(capability_id: str, payload: Dict[str, Any]) -> Dict[str, Any]:
    handle = _handler_for(capability_id)
    result = handle(dict(payload or {}))
    if not isinstance(result, dict):
        return {"ok": False, "error": "handler returned " + type(result).__name__}
    return result


def _register_capability(capability_id: str) -> None:
    entity = capability_id

    @router.post("/" + capability_id)
    async def create(payload: Dict[str, Any], request: Request) -> Dict[str, Any]:
        tenant = require_platform_token(request)
        _refuse_caller_tenancy(payload)
        reject_invalid_payload(capability_id, payload)
        # A capability that calls a DECLARED placeholder connector answers the
        # typed unavailable refusal -- after auth and payload checks, so 401 and
        # 422 still hold, and before the handler, so nothing is stored.
        placeholder = refusal_for(capability_id)
        if placeholder is not None:
            return JSONResponse(status_code=UNAVAILABLE_STATUS, content=placeholder)
        result = _dispatch_capability(capability_id, payload)
        if result.get("ok") is False:
            # Fail closed: the request is refused and NOTHING is persisted.
            return result

            return result
        record = dict(payload or {})
        try:
            stored = store.save(entity, record, tenant_id=tenant.tenant_id)
        except Exception as exc:  # storage refusal is a refused write
            # An error body is read by whoever asked; it must never carry a
            # token, a connection string or a password out of the process.
            return {
                "ok": False,
                "capability": capability_id,
                "error": sanitise_error("%s: %s" % (type(exc).__name__, exc)),
            }
        return {
            "ok": True,
            "capability": capability_id,
            "result": result,
            "stored": stored,
        }

    @router.get("/" + capability_id)
    def list_records(request: Request) -> Dict[str, Any]:
        tenant = require_platform_token(request)
        allowed = set(store.COLUMNS[entity]) | CONTROLS
        given = dict(request.query_params)
        unknown = sorted(k for k in given if k not in allowed)
        if unknown:
            return {
                "ok": False,
                "error": "unknown query field(s): " + ", ".join(unknown),
            }
        try:
            return store.query(
