                "capability": capability_id,
                "error": sanitise_error("%s: %s" % (type(exc).__name__, exc)),
            }
        if updated is None:
            raise HTTPException(status_code=404, detail="not found")
        return {
            "ok": True,
            "capability": capability_id,
            "result": result,
            "stored": updated,
        }

    @router.delete("/" + capability_id + "/{item_id}")
