def tenant_pairs() -> List[Tuple[str, str]]:
    """``(token, tenant)`` pairs declared by ``TENANT_TOKENS``."""
    out: List[Tuple[str, str]] = []
    for chunk in (os.environ.get(TENANT_TOKENS_ENV) or "").split(","):
        chunk = chunk.strip()
        if not chunk or ":" not in chunk:
            continue
        token, _, tenant = chunk.partition(":")
        token, tenant = token.strip(), tenant.strip()
        if token and tenant:
            out.append((token, tenant))
    return out


def tenant_of(headers: Dict[str, str]) -> str:
