def _kind(capability_id: str, field: str) -> str:
    cls = model(capability_id)
    attr = (getattr(cls, "_FIELD_PY", {}) or {}).get(field, field)
    declared = str((getattr(cls, "__annotations__", {}) or {}).get(attr, "str"))
    for word, kind in (("bool", "bool"), ("float", "float"), ("int", "int")):
        if word in declared:
            return kind
    return "str"


def _temporal_kind(capability_id: str, field: str) -> str:
    declared = constraints(capability_id).get(field) or {}
    fmt = str(declared.get("format") or "").strip().lower()
    if fmt in ("date", "datetime", "timestamp", "iso8601", "time"):
        return "datetime" if fmt in ("timestamp", "iso8601") else fmt
    low = field.lower()
    if low.endswith("_at") or "datetime" in low:
        return "datetime"
    if low.endswith("_date") or low.endswith("_day"):
        return "date"
    if low.endswith("_time"):
        return "time"
    return ""


def _temporal_sample(kind: str) -> str:
    """A temporal value in the PAST, so a rule about the future is not
    tripped by the sample itself."""
    if kind == "date":
        return days_from_today(-10)
    if kind == "time":
        return "10:00:00"
    return (
        datetime.datetime.now() - datetime.timedelta(days=10)
    ).replace(microsecond=0).isoformat()


def _model_default(capability_id: str, field: str) -> Tuple[Any, bool]:
    cls = model(capability_id)
    if not dataclasses.is_dataclass(cls):
        return None, False
    attr = (getattr(cls, "_FIELD_PY", {}) or {}).get(field, field)
    for item in dataclasses.fields(cls):
        if item.name != attr:
            continue
        if item.default is not dataclasses.MISSING:
            return item.default, True
        if item.default_factory is not dataclasses.MISSING:
            try:
                return item.default_factory(), True
            except Exception:  # noqa: BLE001 -- an unusable default is no default
                return None, False
    return None, False


def field_sample(capability_id: str, field: str) -> Any:
    """A value the capability's own model declares acceptable for ``field``.

    Vocabulary first, then a declared format (an email is an email, a date is
    a past date), then the model's own dataclass default when it is usable,
    then the type's neutral sample raised to any declared ``min`` and capped
    to any declared ``max``.
    """
    rules = constraints(capability_id).get(field) or {}
    allowed = rules.get("allowed_values")
    if allowed:
        return list(allowed)[0]
    if str(rules.get("format") or "").strip().lower() == "email":
        return _EMAIL_SAMPLE
    temporal = _temporal_kind(capability_id, field)
    if temporal:
        return _temporal_sample(temporal)
    default, present = _model_default(capability_id, field)
    low = rules.get("min")
    high = rules.get("max")
    if present and default not in (None, "") and not isinstance(default, bool):
        if not isinstance(default, (int, float)) or default:
            if low is None or not isinstance(default, (int, float)) or default >= low:
                return default
    sample: Any = _SAMPLE_BY_TYPE.get(_kind(capability_id, field), "sample")
    if isinstance(sample, (int, float)) and not isinstance(sample, bool):
        if low is not None and sample < low:
            sample = low
        if high is not None and sample > high:
            sample = high
    return sample


def sample_payload(capability_id: str) -> Dict[str, Any]:
    """The schema sample: one declared-acceptable value per declared field."""
    return {name: field_sample(capability_id, name) for name in fields(capability_id)}


def payload_for(capability_id: str, **overrides: Any) -> Dict[str, Any]:
    """The schema sample with named fields overridden.

    Payloads are built from the model's own declared fields and constraints,
    never hand-written: a field the model does not declare cannot be sent.
    """
    payload = sample_payload(capability_id)
    unknown = sorted(name for name in overrides if name not in payload)
    if unknown:
        raise KeyError(
            "%s does not declare %s" % (capability_id, ", ".join(unknown))
        )
    payload.update(overrides)
    return payload


def partial_payload(capability_id: str, drop: Sequence[str] = ()) -> Dict[str, Any]:
    """The sample with named fields removed (default: the first required)."""
    payload = sample_payload(capability_id)
    for name in drop or (required_field(capability_id),):
        payload.pop(name, None)
    return payload


