def post(
    client: Any,
    capability_id: str,
    payload: Any,
    headers: Optional[Dict[str, str]] = None,
    suffix: str = "",
) -> Any:
    return client.post(url(capability_id, suffix), json=payload, headers=dict(headers or AUTH))


def get(
    client: Any,
    capability_id: str,
    suffix: str = "",
    headers: Optional[Dict[str, str]] = None,
) -> Any:
    return client.get(url(capability_id, suffix), headers=dict(headers or AUTH))


def created_id(response: Any) -> Tuple[Optional[int], str]:
    """``(record_id, refusal)`` from a create answer.

    The id is the one the store assigned, read from the stored record --
    never guessed from a count.
    """
    try:
        body = response.json()
    except Exception:  # noqa: BLE001
        return None, "unparseable body"
    if not isinstance(body, dict):
        return None, "non-object body"
    if body.get("ok") is False:
        return None, str(body.get("error") or body.get("error_kind") or "refused")
    stored = body.get("stored")
    record_id = stored.get("id") if isinstance(stored, dict) else None
    if not isinstance(record_id, int) or isinstance(record_id, bool):
        return None, "no stored id in the answer"
    return record_id, ""


def create_record(
    client: Any,
    capability_id: str,
    headers: Optional[Dict[str, str]] = None,
    **overrides: Any,
) -> Tuple[Optional[int], Any]:
    """Create one record through the capability's own POST route.

    Returns ``(record_id, response)``; ``record_id`` is None when the route
    refused -- the refusal is the response, and the caller reports it.
    """
    payload = payload_for(capability_id, **overrides) if overrides else sample_payload(capability_id)
    response = post(client, capability_id, payload, headers)
    record_id, _refusal = created_id(response)
    return record_id, response


def list_records(
    client: Any,
    capability_id: str,
    headers: Optional[Dict[str, str]] = None,
    limit: int = 500,
) -> Dict[str, Any]:
    response = get(client, capability_id, "?limit=%d" % limit, headers)
    assert response.status_code == 200, (capability_id, response.status_code, response.text)
    return dict(response.json())


def total_records(
    client: Any,
    capability_id: str,
    headers: Optional[Dict[str, str]] = None,
) -> int:
    return int(list_records(client, capability_id, headers).get("total") or 0)


def record_ids(
    client: Any,
    capability_id: str,
    headers: Optional[Dict[str, str]] = None,
) -> List[Any]:
    return [item.get("id") for item in list_records(client, capability_id, headers)["items"]]


def plant_record(
    capability_id: str, tenant_id: str, record: Optional[Dict[str, Any]] = None
) -> int:
    """Write one record for ``tenant_id`` straight through the store.

    Used to prove cross-tenant invisibility for a capability whose POST
