# --- rejection as data ----------------------------------------------------


def rejection(response: Any) -> Optional[Tuple[str, Any, Any]]:
    """The product's structured refusal: (field, reason, allowed) or None.

    Read from the headers the product states, never from prose.
    """
    headers = getattr(response, "headers", {}) or {}
    field = headers.get("X-Rejected-Field")
    if field is not None:
        try:
            field = json.loads(field)
        except ValueError:
            return None
        reason = headers.get("X-Rejection-Reason")
        raw_allowed = headers.get("X-Allowed-Values")
        try:
            allowed = json.loads(raw_allowed) if raw_allowed is not None else None
        except ValueError:
            allowed = None
        return field, reason, allowed
    try:
        body = response.json()
    except Exception:  # noqa: BLE001
        return None
    if not isinstance(body, dict) or "rejected_field" not in body:
        return None
    return (
        body.get("rejected_field"),
        body.get("rejection_reason"),
        body.get("allowed_values"),
    )


def refused(response: Any) -> bool:
    """A refusal, by status or by the envelope's own ``ok: false``.

    The typed unavailable refusal (HTTP 503, ``error_kind`` "unavailable") of
    a capability whose connector is a declared placeholder is a refusal too.
    """
    if response.status_code in REFUSED:
        return True
    if response.status_code not in ACCEPTED + (UNAVAILABLE_STATUS,):
        return False
    try:
        body = response.json()
    except Exception:  # noqa: BLE001
        return False
    if not isinstance(body, dict) or body.get("ok") is not False:
        return False
    return response.status_code in ACCEPTED or body.get("error_kind") == "unavailable"


