 * Command centre: the claims intake board.
 *
 * Reads the capability roster the platform declares (GET /v1/capabilities),
 * measures how many records this tenant holds per capability (GET
 * /v1/<capability>, built from the roster id by {@link apiRoute}), and drives
 * the first real claim journey: register a claim (POST /v1/claim_registration)
 * and then read the same route back (GET /v1/claim_registration) so the record
 * the platform stored is shown next to the answer it gave.
 *
 * Everything shown came back from the server in this session. A refused read is
 * reported with its own status — including the typed 503 refusal of a
 * capability whose connector is a declared placeholder — never filled in.
 */
import React, { useCallback, useEffect, useState } from "react";

import {
  Api,
  ApiResult,
  apiRoute,
  asItems,
  authorityBlock,
  authorityLabel,
  describeResult,
  isPlaceholderRefusal,
} from "./api";

type Capability = { id: string; entity?: string; fields?: string[]; blocks?: string[] };

const CLAIM_FIELDS = [
  "claim_reference",
  "policy_number",
  "claimant_name",
  "incident_date",
  "incident_description",
  "vehicle_registration",
  "claim_amount",
];

export default function CommandCenter({ api }: { api: Api }): React.ReactElement {
  const [capabilities, setCapabilities] = useState<Capability[] | null>(null);
  const [counts, setCounts] = useState<Record<string, string>>({});
  const [error, setError] = useState("");
  const [draft, setDraft] = useState<Record<string, string>>({ claim_reference: "", policy_number: "" });
  const [lastWrite, setLastWrite] = useState<ApiResult | null>(null);
  const [claimList, setClaimList] = useState<ApiResult | null>(null);
  const [stored, setStored] = useState<unknown>(null);

  const registration = apiRoute("claim_registration");

  const refresh = useCallback(async () => {
    setError("");
    const listed = await api("GET", "/v1/capabilities");
    if (!listed.ok || !listed.body) {
      setError(describeResult(listed));
      return;
    }
    const items = (listed.body as { items?: Capability[] }).items || [];
    setCapabilities(items);
    const next: Record<string, string> = {};
    for (const capability of items) {
      // The route is the platform prefix concatenated with the id the roster
      // returned; no capability path is written out by hand here.
      const result = await api("GET", apiRoute(capability.id) + "?limit=500");
      next[capability.id] = isPlaceholderRefusal(result)
        ? "HTTP 503 — connector not configured"
        : result.ok
        ? `${asItems(result.body).length} record(s)`
        : `HTTP ${result.status}`;
    }
    setCounts(next);
  }, [api]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  /** Register the claim, then read the registration route back. */
  async function registerClaim(): Promise<void> {
    const record: Record<string, string> = {};
    Object.entries(draft).forEach(([key, value]) => {
      if (String(value || "").trim()) record[key] = String(value).trim();
    });
    if (!Object.keys(record).length) {
      setError("Fill at least one claim field: the console will not post an empty record.");
      return;
    }
    setError("");
    const posted = await api("POST", registration, record);
    setLastWrite(posted);
    setStored(posted.body && typeof posted.body === "object" ? (posted.body as Record<string, unknown>).stored ?? null : null);
    if (!posted.ok) {
      // Fail closed: the route stored nothing, so there is no list to read.
      setClaimList(null);
      return;
    }
    setClaimList(await api("GET", registration + "?limit=50"));
  }

  async function listClaims(): Promise<void> {
    setError("");
    setClaimList(await api("GET", registration + "?limit=50"));
  }

  const claims = claimList ? asItems(claimList.body) : [];

  return (
    <section>
      <h2>Command centre — claims intake</h2>
      <p>
        What this tenant holds per capability, measured from the live routes, and the first claims
        journey: register a claim, then read it back from the same route.
      </p>
      {error ? <pre>{error}</pre> : null}

      <div style={{ ...card, borderColor: "rgba(128,128,128,0.4)" }}>
        <h3 style={heading}>Register a claim</h3>
        <p style={dim}>
          Posted to <code>{registration}</code>, then read back with GET on the same route.
        </p>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          {CLAIM_FIELDS.map((field) => (
            <label key={field} style={fieldLabel}>
              {field}
              <input
                value={draft[field] || ""}
                placeholder={field === "claim_reference" ? "CLM-2024-0001" : field === "policy_number" ? "POL-88213" : ""}
                onChange={(event) => setDraft({ ...draft, [field]: event.target.value })}
              />
            </label>
          ))}
        </div>
        <div style={{ marginTop: 8, display: "flex", gap: 8 }}>
          <button onClick={() => void registerClaim()}>Register claim</button>
          <button onClick={() => void listClaims()}>List claims</button>
        </div>
        {lastWrite ? (
          <div style={card}>
            <div style={dim}>{describeResult(lastWrite)}</div>
            {isPlaceholderRefusal(lastWrite) ? (
              <p style={{ color: "#c60" }}>
                Connector not configured: the platform refused this capability with its typed 503
                refusal. Nothing was stored.
              </p>
            ) : null}
            <span style={chip}>authority: {authorityLabel(lastWrite.body)}</span>
            <pre style={pre}>{JSON.stringify(lastWrite.body, null, 2)}</pre>
          </div>
        ) : null}
        {stored ? (
          <div>
            <div style={dim}>stored record, verbatim</div>
            <pre style={pre}>{JSON.stringify(stored, null, 2)}</pre>
          </div>
        ) : null}
        {claimList ? (
          <div>
            <div style={dim}>{describeResult(claimList)}</div>
            {claims.length ? (
              <table style={{ borderCollapse: "collapse", width: "100%", fontSize: 13 }}>
                <thead>
                  <tr>
                    {["id", "claim_reference", "policy_number", "status", "claim_amount"].map((column) => (
                      <th key={column} style={cell}>
                        {column}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {claims.slice(0, 10).map((row, index) => (
                    <tr key={String(row.id ?? index)}>
                      {["id", "claim_reference", "policy_number", "status", "claim_amount"].map((column) => (
                        <td key={column} style={cell}>
                          {row[column] === undefined || row[column] === null ? "—" : String(row[column])}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            ) : (
              <p style={dim}>The platform returned 0 claim record(s) for this tenant on this route.</p>
            )}
            {authorityBlock(claimList.body) ? (
              <pre style={pre}>{JSON.stringify(authorityBlock(claimList.body), null, 2)}</pre>
            ) : null}
          </div>
        ) : null}
      </div>

      <h3 style={heading}>Capabilities carried by this build</h3>
      {capabilities === null ? (
        <p>Loading capabilities…</p>
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(240px, 1fr))", gap: 8 }}>
          {capabilities.map((capability) => (
            <div key={capability.id} style={card}>
              <div style={{ fontWeight: 600 }}>{capability.id}</div>
              <div style={{ opacity: 0.8, fontSize: 12 }}>{counts[capability.id] || "…"}</div>
              <div style={dim}>{apiRoute(capability.id)}</div>
              <div style={{ opacity: 0.6, fontSize: 11 }}>
                blocks: {(capability.blocks || []).join(", ") || "none"}
              </div>
            </div>
          ))}
        </div>
      )}
      <button onClick={() => void refresh()}>Refresh</button>
    </section>
  );
}

const card: React.CSSProperties = {
  border: "1px solid rgba(128,128,128,0.25)",
  borderRadius: 8,
  padding: 12,
  margin: "12px 0",
};
const heading: React.CSSProperties = { fontSize: 15, marginBottom: 4 };
const dim: React.CSSProperties = { opacity: 0.75, fontSize: 13 };
const pre: React.CSSProperties = {
