const ROUTING_FIELDS = ["claim_reference", "adjuster_name", "routing_reason", "approval_decision", "approval_authority"];

export default function OperationalChat({ api }: { api: Api }): React.ReactElement {
  const [draft, setDraft] = useState<Record<string, string>>({ approval_decision: "approved" });
  const [routed, setRouted] = useState<ApiResult | null>(null);
  const [routedList, setRoutedList] = useState<ApiResult | null>(null);
  const [notified, setNotified] = useState<ApiResult | null>(null);
  const [status, setStatus] = useState("");

  const routing = apiRoute("adjuster_routing_approval");
  const notifications = apiRoute("claimant_notifications");

  function payload(): Record<string, string> {
    const record: Record<string, string> = {};
    Object.entries(draft).forEach(([key, value]) => {
      if (String(value || "").trim()) record[key] = String(value).trim();
    });
    return record;
  }

  async function routeForApproval(): Promise<void> {
    const record = payload();
    if (!Object.keys(record).length) {
      setStatus("Fill at least one routing field: the desk will not post an empty routing request.");
      return;
    }
    setStatus("routing…");
    const posted = await api("POST", routing, record);
    setRouted(posted);
    if (!posted.ok) {
      setRoutedList(null);
      setStatus(describeResult(posted));
      return;
    }
    setRoutedList(await api("GET", routing + "?limit=50"));
    setStatus(describeResult(posted));
  }

  async function listRouted(): Promise<void> {
    const listed = await api("GET", routing + "?limit=50");
    setRoutedList(listed);
    setStatus(describeResult(listed));
  }

