    const record = payload();
    if (!record.claim_reference) {
      setStatus("A claimant notification needs claim_reference: the desk will not notify about a claim it cannot name.");
      return;
    }
    const posted = await api("POST", notifications, {
      claim_reference: record.claim_reference,
