                    ? "CLM-2024-0001"
                    : field === "adjuster_name"
                    ? "J. Okafor"
                    : field === "routing_reason"
                    ? "estimate above the fast-track threshold"
                    : field === "approval_authority"
                    ? "senior adjuster"
