        </div>
        <div style={{ marginTop: 8, display: "flex", gap: 8, flexWrap: "wrap" }}>
          <button onClick={() => void routeForApproval()}>Route claim for adjuster approval</button>
          <button onClick={() => void listRouted()}>List routed claims</button>
          <button onClick={() => void recordNotification()}>Notify the claimant</button>
        </div>
        <p style={dim}>{status}</p>
      </div>

      {routed ? <ResponseView result={routed} title="routing answer" /> : null}
      {routedList ? <ResponseView result={routedList} title="routed claims read back" /> : null}
      {notified ? <ResponseView result={notified} title="claimant notification" /> : null}

      {routedList && routedList.ok ? (
        routedRows.length ? (
          <table style={{ borderCollapse: "collapse", width: "100%", fontSize: 13 }}>
            <thead>
              <tr>
                {["id", "claim_reference", "adjuster_name", "approval_decision", "status"].map((column) => (
                  <th key={column} style={cell}>
                    {column}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {routedRows.slice(0, 10).map((row, index) => (
                <tr key={String(row.id ?? index)}>
                  {["id", "claim_reference", "adjuster_name", "approval_decision", "status"].map((column) => (
                    <td key={column} style={cell}>
                      {row[column] === undefined || row[column] === null ? "—" : String(row[column])}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <p style={dim}>No claim has been routed for approval on this tenant yet.</p>
        )
      ) : null}
    </section>
  );
}

/** One answer, rendered whole: status, authority, refusal, then the body. */
function ResponseView({ result, title }: { result: ApiResult; title: string }): React.ReactElement {
  const lines = refusalLines(result);
